// 각 문서를 단어로 쪼개, 단어 → 문서 목록(posting list)을 쌓는다
function buildIndex(docs) {
  const index = {};
  for (const doc of docs) {
    const tokens = tokenize(doc.text);        // 단어로 쪼개기(토큰화)
    for (const term of tokens) {
      if (!index[term]) index[term] = [];
      if (!index[term].includes(doc.id))
        index[term].push(doc.id);             // 이 단어 → 이 문서 기록
    }
  }
  return index;
}
// 문서1 고양이 사료 추천, 문서2 강아지 사료 후기 →
//   고양이→[1]  사료→[1,2]  추천→[1]  강아지→[2]  후기→[2]
